html_parts.append('<p><strong>AI FOR SMALL BUSINESS</strong></p>')
html_parts.append('<p><em>A Practical Playbook for Modern Innovation</em></p>')
html_parts.append('<p style="margin-top:40px;">© 2026 MIFECO Virtual Operations</p>')
html_parts.append('<p>All rights reserved.</p>')
