    # Skip the initial header/front matter - we handle it above
    if skip_until_body:
        if stripped.startswith('## Chapter'):
            skip_until_body = False
            body_lines.append(line)
        continue

    # Convert markdown to HTML
    if stripped.startswith('## Chapter'):
        # Chapter header
        chapter_title = stripped.replace('## ', '')
        body_lines.append(f'<div class="chapter">')
        body_lines.append(f'<h2>{chapter_title}</h2>')
