        body_lines.append(f'<h3>{stripped.replace("### ", "")}</h3>')
    elif stripped.startswith('---'):
        body_lines.append('<hr>')
    elif stripped == '':
        body_lines.append('<br>')
    elif stripped.startswith('> '):
        body_lines.append(f'<blockquote>{stripped[2:]}</blockquote>')
    elif stripped.startswith('- '):
        body_lines.append(f'<li>{stripped[2:]}</li>')
    elif stripped.startswith('* ') or stripped.startswith('+ '):
        body_lines.append(f'<li>{stripped[2:]}</li>')
    elif stripped.startswith('1.') or stripped.startswith('2.') or stripped.startswith('3.'):
        body_lines.append(f'<li>{stripped[3:]}</li>')
    else:
        # Regular paragraph - wrap in <p>
        if stripped:
            body_lines.append(f'<p>{stripped}</p>')

# Close any open chapter divs
body_lines.append('</div>')

html_parts.append('<div class="toc-page">')
